import{_ as i,o as a,c as t,a2 as e}from"./chunks/framework.D5wUhsuj.js";const p=JSON.parse('{"title":"快速注册","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start/register.md","filePath":"quick-start/register.md"}'),r={name:"quick-start/register.md"};function o(s,l,n,h,c,u){return a(),t("div",null,[...l[0]||(l[0]=[e('<h1 id="快速注册" tabindex="-1">快速注册 <a class="header-anchor" href="#快速注册" aria-label="Permalink to &quot;快速注册&quot;">​</a></h1><h2 id="注册方式" tabindex="-1">注册方式 <a class="header-anchor" href="#注册方式" aria-label="Permalink to &quot;注册方式&quot;">​</a></h2><p>CipherGate 支持两种注册方式：</p><h3 id="_1-应用用户注册" tabindex="-1">1. 应用用户注册 <a class="header-anchor" href="#_1-应用用户注册" aria-label="Permalink to &quot;1. 应用用户注册&quot;">​</a></h3><p>适用于被应用管理员邀请的终端用户。</p><h4 id="注册步骤" tabindex="-1">注册步骤 <a class="header-anchor" href="#注册步骤" aria-label="Permalink to &quot;注册步骤&quot;">​</a></h4><ol><li><p><strong>获取注册链接</strong></p><ul><li>向应用管理员获取专属注册链接</li><li>链接格式：<code>https://your-domain/register?id=应用ID</code></li></ul></li><li><p><strong>填写注册信息</strong></p><ul><li>用户名：2-50 个字符，支持字母、数字、下划线、中划线</li><li>工作邮箱：用于接收验证码</li><li>邮箱验证码：6 位数字</li><li>登录密码：至少 8 位，需包含字母和数字</li></ul></li><li><p><strong>完成注册</strong></p><ul><li>点击「注册」按钮</li><li>注册成功后可直接登录</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">提示</p><ul><li>验证码有效期为 60 秒</li><li>如未收到验证码，请检查垃圾邮件</li></ul></div><h3 id="_2-开发者注册" tabindex="-1">2. 开发者注册 <a class="header-anchor" href="#_2-开发者注册" aria-label="Permalink to &quot;2. 开发者注册&quot;">​</a></h3><p>适用于需要创建和管理应用的开发者。</p><h4 id="注册步骤-1" tabindex="-1">注册步骤 <a class="header-anchor" href="#注册步骤-1" aria-label="Permalink to &quot;注册步骤&quot;">​</a></h4><ol><li><p><strong>访问首页</strong></p><ul><li>打开平台首页</li><li>点击「应用用户登录」或「开发者登录」</li></ul></li><li><p><strong>创建账号</strong></p><ul><li>在登录弹窗中选择「注册」</li><li>填写邮箱、密码等信息</li><li>完成邮箱验证</li></ul></li><li><p><strong>开始使用</strong></p><ul><li>登录后进入开发者后台</li><li>可以创建和管理应用</li></ul></li></ol><h2 id="注册后下一步" tabindex="-1">注册后下一步 <a class="header-anchor" href="#注册后下一步" aria-label="Permalink to &quot;注册后下一步&quot;">​</a></h2><ul><li><a href="/docs/quick-start/login.html">首次登录</a> - 了解如何登录平台</li><li><a href="/docs/developer/application.html">应用管理</a> - 创建你的第一个应用</li></ul>',14)])])}const _=i(r,[["render",o]]);export{p as __pageData,_ as default};
